# Factual premises: Kathmandu, Bogota, Abuja, Minsk, Baghdad, and Oslo
# are the respective capitals.
facts = {
    "The capital of Nepal is Pokhara.": False,
    "The capital of Colombia is Bogota.": True,
    "The capital of the Nigeria is Abuja.": True,
    "The capital of Belarus is Grodno.": False,
    "The capital of Iraq is Beirut.": False,
    "The capital of Nepal is Kathmandu.": True,
    "The capital of Norway is Oslo.": True,
    "The capital of Norway is Bergen.": False,
}


def evaluate(node):
    """Interpret only the arithmetic and Boolean syntax used in the question."""
    if isinstance(node, ast.Expression):
        return evaluate(node.body)
    if isinstance(node, ast.Constant):
        if type(node.value) in (int, bool):
            return node.value
    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return Fraction(left) / Fraction(right)
    if isinstance(node, ast.BoolOp):
        values = [evaluate(child) for child in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        results = []
        for op, child in zip(node.ops, node.comparators):
            right = evaluate(child)
            if isinstance(op, ast.LtE):
                results.append(left <= right)
            elif isinstance(op, ast.Gt):
                results.append(left > right)
            else:
                raise ValueError("Unsupported comparison")
            left = right
        return all(results)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        if node.keywords:
            raise ValueError("Unexpected keyword arguments")
        args = [evaluate(child) for child in node.args]
        if node.func.id == "max":
            return max(args)
        if node.func.id == "min":
            return min(args)
    raise ValueError("Unsupported syntax: " + ast.dump(node))


def main():
    results = {}
    for label, text in expressions.items():
        for proposition, truth in facts.items():
            text = text.replace(proposition, str(truth))
        text = text.replace("is less than or equal to", "<=")
        text = text.replace("is greater than", ">")
        results[label] = evaluate(ast.parse(text, mode="eval"))
        if type(results[label]) is not bool:
            raise ValueError("Expression did not produce a Boolean")
        print(f"{label} = {results[label]}")

    true_options = [label for label, value in results.items() if value]
    print("True options:", ", ".join(true_options) or "none")
    print("Submitted option B:", results["B"])
    print("CHECK PASS" if true_options == ["B"] else "CHECK FAIL")


try:
    main()
except (SyntaxError, ValueError, TypeError, ZeroDivisionError) as exc:
